package org.jsoup.select;

import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;

import java.util.stream.Stream;

/**
 * Internal support for the {@code :scope} pseudo-class.
 * <p>{@code :scope} binds to the {@code root} element passed into an Evaluator's {@link Evaluator#matches matches()},
 * which is the element on which {@link Element#select(String)} was invoked. It does not hold any element itself, so a
 * compiled Evaluator can be reused against different roots, and a {@code :scope} nested inside a {@code :has()} binds to
 * that {@code :has()} candidate, because {@link StructuralEvaluator.Has} supplies the candidate as the matching root for
 * its inner branches.</p>
 * <p>This class provides the three pieces of bookkeeping the rest of the engine needs:</p>
 * <ul>
 *   <li>{@link #validate} enforces that at most one {@code :scope} appears per selector level (a {@code :has()} argument
 *   establishes a new level; {@code :not()} is parsed independently);</li>
 *   <li>{@link #usesScope} reports whether a level's evaluator binds to its root, so that the {@link Collector} candidate
 *   domain can be widened from the root and its descendants to also include its following element siblings (required by
 *   {@code :scope + ...} and {@code :scope ~ ...}), without ever walking above the root;</li>
 *   <li>the scoped candidate streams themselves, in document order.</li>
 * </ul>
 */
final class ScopeSelector {
    private ScopeSelector() {}

    /**
     * Validate that {@code :scope} occurs at most once per selector level: once in the top-level selector list, and once
     * in each nested {@code :has()} argument. {@code :is()} is transparent (it establishes no level of its own), while
     * {@code :not()} is parsed independently and already validated by its own parser run.
     * @param group the fully parsed evaluator
     * @param query the original selector text, for error messages
     * @throws Selector.SelectorParseException if a level contains more than one {@code :scope}
     */
    static void validate(Evaluator group, String query) {
        if (countScope(group) > 1)
            throw new Selector.SelectorParseException(
                "Could not parse query '%s': the :scope pseudo-class may appear only once per selector level", query);
        validateNested(group, query);
    }

    /** Recurse into {@code :has()} subtrees and apply the same one-scope-per-level check at each nested level. */
    private static void validateNested(Evaluator eval, String query) {
        if (eval instanceof StructuralEvaluator.Has) {
            Evaluator inner = ((StructuralEvaluator) eval).evaluator;
            if (countScope(inner) > 1)
                throw new Selector.SelectorParseException(
                    "Could not parse query '%s': the :scope pseudo-class may appear only once per selector level", query);
            validateNested(inner, query);
        } else if (eval instanceof StructuralEvaluator.Not) {
            // parsed by a fresh QueryParser, which ran its own validation; nothing here is bound to this root
            return;
        } else if (eval instanceof CombiningEvaluator) {
            for (Evaluator child : ((CombiningEvaluator) eval).evaluators)
                validateNested(child, query);
        } else if (eval instanceof StructuralEvaluator.ImmediateParentRun) {
