     * Count {@code :scope} tokens bound to the enclosing level's root, and recursively validate each {@code :has()}
     * subtree as a new level. {@code :is()}, {@code :not()}, combinators and {@code :nth-child(... of S)} are
     * transparent (they pass the same root through); only {@code :has()} rebinds the anchor.
     */
    private static int countScopeAtLevel(Evaluator eval) {
        if (eval instanceof Evaluator.IsScope)
            return 1;
        if (eval instanceof StructuralEvaluator.Has) {
            validateLevel(((StructuralEvaluator) eval).evaluator, ""); // message unused; replaced below if it fires
            return 0; // its :scope tokens bind to the :has candidate, not to this level
        }
        if (eval instanceof CombiningEvaluator) {
            int count = 0;
            for (Evaluator child : ((CombiningEvaluator) eval).evaluators)
                count += countScopeAtLevel(child);
            return count;
        }
        if (eval instanceof StructuralEvaluator.ImmediateParentRun) {
            int count = 0;
            for (Evaluator child : ((StructuralEvaluator.ImmediateParentRun) eval).evaluators)
                count += countScopeAtLevel(child);
            return count;
        }
        if (eval instanceof StructuralEvaluator) {
            return countScopeAtLevel(((StructuralEvaluator) eval).evaluator); // Ancestor, siblings, Is, Not
        }
        if (eval instanceof Evaluator.CssNthEvaluator) {
            Evaluator filter = ((Evaluator.CssNthEvaluator) eval).filter;
            return filter == null ? 0 : countScopeAtLevel(filter);
        }
        return 0;
    }

    /** Whether this evaluator level references its matching root through {@code :scope} at all. */
    static boolean usesScope(Evaluator eval) {
        return countScopeAtLevel(eval) > 0;
    }

