     * Whether a scope-headed axis-0 branch can match the anchor itself: only when no descendant, child, or sibling edge
     * is crossed to reach the {@code :scope} terminus, e.g. {@code :scope} or {@code :scope.x:has(p)}, but not
     * {@code :scope p} or {@code :scope > p}.
     */
    static boolean selfMatchableScopeBranch(Evaluator branch) {
        Evaluator edge = branch;
        while (true) {
            if (edge instanceof CombiningEvaluator.And) {
                edge = ((CombiningEvaluator.And) edge).evaluators.get(0);
            } else if (edge instanceof StructuralEvaluator.Is) {
                edge = ((StructuralEvaluator) edge).evaluator;
            } else {
                return edge instanceof Evaluator.IsScope;
            }
        }
    }

