        if (eval instanceof CombiningEvaluator.Or) {
            for (Evaluator branch : ((CombiningEvaluator.Or) eval).evaluators) {
                if (scopeSiblingAxis(branch) != 0)
                    return true;
            }
            return false;
        }
        return scopeSiblingAxis(eval) != 0;
    }

    /**
     * The candidate domain for a scoped query that reaches the root's following siblings: the root itself and its
     * descendants, then each following element sibling and that sibling's descendants. The subtrees are disjoint and
     * emitted in document order; non-element siblings of the root are skipped, as they never take part in an element
     * relationship. The tree is only read.
     */
    static Stream<Element> scopedElements(Element root) {
        Stream.Builder<Stream<Element>> streams = Stream.builder();
        streams.add(root.stream());
        for (Element sibling = root.nextElementSibling(); sibling != null; sibling = sibling.nextElementSibling())
            streams.add(sibling.stream());
        return streams.build().flatMap(stream -> stream);
    }

    /** Node-typed variant of {@link #scopedElements(Element)}, for {@code selectNodes()} queries that use {@code :scope}. */
    static <T extends Node> Stream<T> scopedNodes(Element root, Class<T> type) {
        Stream.Builder<Stream<T>> streams = Stream.builder();
        streams.add(root.nodeStream(type));
        for (Element sibling = root.nextElementSibling(); sibling != null; sibling = sibling.nextElementSibling())
            streams.add(sibling.nodeStream(type));
        return streams.build().flatMap(stream -> stream);
    }
}

