     * Whether any top-level branch is anchored by {@code :scope} and leads with a {@code +} or {@code ~} sibling edge,
     * so that the candidate domain must include the root's following element siblings. {@code :has()} subtrees are not
     * inspected: their {@code :scope} binds to a per-candidate anchor and is resolved inside
     * {@link StructuralEvaluator.Has}.
     */
    static boolean needsSiblingDomain(Evaluator eval) {
        return siblingBranches(eval) != null;
    }

    /**
     * Build an evaluator containing only the top-level branches that lead with a {@code :scope}-headed {@code +} or
     * {@code ~} sibling edge. Those are the only branches allowed to match among the root's following siblings and
     * their subtrees; every other branch stays confined to the root and its descendants, preserving the historical
     * descendants-only behavior of queries that do not use {@code :scope}. Returns {@code null} when there is no such
     * branch.
     */
    static @org.jspecify.annotations.Nullable Evaluator siblingBranches(Evaluator eval) {
        java.util.List<Evaluator> matches = new java.util.ArrayList<>();
        if (eval instanceof CombiningEvaluator.Or) {
            for (Evaluator branch : ((CombiningEvaluator.Or) eval).evaluators) {
                if (scopeSiblingAxis(branch) != 0)
                    matches.add(branch);
            }
        } else if (scopeSiblingAxis(eval) != 0) {
            matches.add(eval);
        }
        if (matches.isEmpty())
            return null;
        if (matches.size() == 1)
            return matches.get(0);
        return new CombiningEvaluator.Or(matches);
    }

    /**
     * The root's following element siblings and their descendants, in document order. Non-element siblings are
     * skipped. The tree is only read.
     */
    static Stream<Element> siblingElements(Element root) {
        Stream.Builder<Stream<Element>> streams = Stream.builder();
        for (Element sibling = root.nextElementSibling(); sibling != null; sibling = sibling.nextElementSibling())
            streams.add(sibling.stream());
        return streams.build().flatMap(stream -> stream);
    }

    /** Node-typed variant of {@link #siblingElements(Element)}. */
    static <T extends Node> Stream<T> siblingNodes(Element root, Class<T> type) {
        Stream.Builder<Stream<T>> streams = Stream.builder();
        for (Element sibling = root.nextElementSibling(); sibling != null; sibling = sibling.nextElementSibling())
            streams.add(sibling.nodeStream(type));
        return streams.build().flatMap(stream -> stream);
    }

    /**
     * The root itself and its descendants, in document order.
     */
    static Stream<Element> rootElements(Element root) {
        return root.stream();
    }

    /** Node-typed variant of {@link #rootElements(Element)}. */
    static <T extends Node> Stream<T> rootNodes(Element root, Class<T> type) {
        return root.nodeStream(type);
    }
}

