        Stream<Element> stream = eval.wantsNodes() ?
            streamNodes(eval, root, Element.class) :
            stream(eval, root);
        Elements els = stream.collect(toCollection(Elements::new));
        eval.reset(); // drops any held memos
        return els;
    }

