        evaluator.reset();
        Stream<Element> candidates = ScopeSelector.needsSiblingDomain(evaluator)
            ? ScopeSelector.scopedElements(root)
            : root.stream();
        return candidates.filter(evaluator.asPredicate(root));
    }

