import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class ScopeProbe {
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (Element el : els) { if (sb.length()>0) sb.append(' '); sb.append(el.id().isEmpty()?el.tagName()+el.siblingIndex():el.id()); }
        return sb.toString();
    }
    static void t(Element root, String q) {
        try { System.out.printf("%-40s -> %s%n", q, ids(root.select(q))); }
        catch (Exception e) { System.out.printf("%-40s -> ERR %s%n", q, e.getMessage()); }
    }
    public static void main(String[] args) {
        Document doc = Jsoup.parse(
            "<div id=outer><p id=p1>one<span id=s1></span></p>text<!--c--><p id=p2>two</p><em id=e1></em></div>" +
            "<p id=p3>three</p>");
        Element outer = doc.expectFirst("#outer");
        Element p1 = doc.expectFirst("#p1");
        t(outer, ":scope");
        t(outer, ":scope > p");
        t(outer, ":scope p");
        t(outer, ":scope + p");
        t(outer, ":scope ~ p");
        t(outer, ":scope ~ *");
        t(p1, ":scope + p");
        t(p1, ":scope ~ p");
        t(outer, ":scope[class], :scope ~ p");
        t(outer, ":scope ~ p, div p");
        t(outer, "div p");
        t(doc, ":scope");
        t(doc, ":scope > html > body");
        t(doc, ":scope head");
        // nested has
        t(doc, "div:has(:scope > p)");
        t(doc, "p:has(:scope + em)");
        t(doc, "div:has(p:has(:scope span))");
        t(doc, "section:has(article:has(:scope + h2))");
        // errors
        for (String q : new String[]{":scope :scope", ":scope, :scope", "div:has(:scope :scope)", ":scope >", ", p", "p,", "div:has(", ":scope(", ":bogus", ":scope > > p"})
            t(outer, q);
        // is / not / nth
        t(outer, ":is(:scope) > p");
        t(outer, ":scope:not(.x)");
        t(outer, ":scope > p:nth-child(1 of :scope)");
        t(outer, ":scope > p:not(:scope)");
    }
}
