abstract class StructuralEvaluator extends Evaluator {
    final Evaluator evaluator;
    boolean wantsNodes; // if the evaluator requested nodes, not just elements
    /** Whether this edge's subtree binds to the matching root through a {@code :scope} at its own level. */
    final boolean scopeBound;
    /** Whether this edge's right-hand target is {@code :scope} (as in {@code p + :scope}), so the root itself is a valid match. */
    boolean targetScope;

    public StructuralEvaluator(Evaluator evaluator) {
        this.evaluator = evaluator;
        wantsNodes = evaluator.wantsNodes();
        scopeBound = ScopeSelector.usesScope(evaluator);
    }

    /**
     * Whether the usual "never walk to or above the matching root" guard of a structural edge should be lifted for a
     * candidate that is the root itself. The guard stays in force for ordinary queries, preserving their
     * descendants-only semantics; it is lifted only when the edge participates in a {@code :scope} relationship,
     * either because its left-hand subtree contains a {@code :scope} ({@code :scope > p}) or because its target is a
     * {@code :scope} ({@code p > :scope}). In both cases the edge's own matching logic bounds the walk to exactly the
     * parent/sibling steps the selector requests, so no element outside the relationship can be returned.
     */
    final boolean rootAllowedAtEdge() {
        return scopeBound || targetScope;
    }

