/**
 * Validate {@code :scope} usage at every scope level: it may appear at most once per level, and only in a branch's
 * leading compound selector -- it may be refined by further simple selectors and drive leading combinators, but may
 * not follow a descendant, child, or sibling combinator. Each {@code :has()} argument establishes a new level with
 * its own anchor.
 * @param group the fully parsed evaluator
 * @param query the original selector text, for error messages
 * @throws Selector.SelectorParseException if a level repeats {@code :scope} or places it after a combinator
 */
static void validate(Evaluator group, String query) {
    walkLevel(group, false, query);
}

/**
 * Walk one scope level, counting its {@code :scope} tokens and enforcing their leading-compound position.
 * @param postEdge whether the walk has crossed a combinator edge at this level (a later {@code :scope} is invalid)
 * @return the number of {@code :scope} tokens bound to this level
 */
private static int walkLevel(Evaluator eval, boolean postEdge, String query) {
    if (eval instanceof Evaluator.IsScope) {
        if (postEdge)
            throw new Selector.SelectorParseException(
                "Could not parse query '%s': the :scope pseudo-class may only be used in the leading compound of a selector",
                query);
        return 1;
    }
    if (eval instanceof StructuralEvaluator.Has) {
        if (walkLevel(((StructuralEvaluator) eval).evaluator, false, query) > 1)
            throw new Selector.SelectorParseException(
                "Could not parse query '%s': the :scope pseudo-class may appear only once per selector level", query);
        return 0; // its :scope tokens bind to the :has candidate, a different level
    }
    if (eval instanceof CombiningEvaluator.And) {
        ArrayList<Evaluator> members = ((CombiningEvaluator.And) eval).evaluators; // original (unsorted) order
        Evaluator first = members.get(0);
        boolean edgeFirst = first instanceof StructuralEvaluator.Ancestor
            || first instanceof StructuralEvaluator.ImmediatePreviousSibling
            || first instanceof StructuralEvaluator.PreviousSibling;
        int count = 0;
        if (edgeFirst) {
            count += walkLevel(first, postEdge, query); // the edge's left-hand side
            for (int i = 1; i < members.size(); i++)
                count += walkLevel(members.get(i), true, query); // the right-hand side follows the edge
        } else {
            for (Evaluator member : members)
                count += walkLevel(member, postEdge, query); // a plain compound: no edge crossed here
        }
        return count;
    }
    if (eval instanceof CombiningEvaluator.Or) {
        int count = 0;
        for (Evaluator branch : ((CombiningEvaluator.Or) eval).evaluators)
            count += walkLevel(branch, postEdge, query);
        return count;
    }
    if (eval instanceof StructuralEvaluator.ImmediateParentRun) {
        ArrayList<Evaluator> steps = ((StructuralEvaluator.ImmediateParentRun) eval).evaluators;
        int count = walkLevel(steps.get(0), postEdge, query);
        for (int i = 1; i < steps.size(); i++)
            count += walkLevel(steps.get(i), true, query);
        return count;
    }
    if (eval instanceof StructuralEvaluator) { // Ancestor / sibling left sides, transparent Is / Not
        return walkLevel(((StructuralEvaluator) eval).evaluator, postEdge, query);
    }
    if (eval instanceof Evaluator.CssNthEvaluator) {
        Evaluator filter = ((Evaluator.CssNthEvaluator) eval).filter;
        return filter == null ? 0 : walkLevel(filter, postEdge, query);
    }
    return 0;
}

/**
 * Whether the left-most terminus of the given simple-sequence chain is {@code :scope}, optionally refined by
 * further simple selectors (as in {@code :scope.x}) or wrapped in {@code :is(...)}. Crossing any combinator edge
 * (descendant, child, sibling) or reaching a plain selector such as a tag terminates the chain without a match.
 * The synthetic {@link StructuralEvaluator.Root} produced by a leading-combinator query (e.g. {@code > p}) is not
 * {@code :scope}.
 */
static boolean isScopeAnchor(Evaluator edge) {
    while (true) {
        if (edge instanceof Evaluator.IsScope)
            return true;
        if (edge instanceof CombiningEvaluator.And)
            edge = ((CombiningEvaluator.And) edge).evaluators.get(0);
        else if (edge instanceof StructuralEvaluator.Is)
            edge = ((StructuralEvaluator.Is) edge).evaluator;
        else
            return false;
    }
}

/**
 * Whether the given evaluator references its matching root through {@code :scope} at its own level (a
 * {@code :scope} inside a nested {@code :has()} binds to that {@code :has()} candidate and is resolved there, so it
 * does not count).
 */
static boolean usesScope(Evaluator eval) {
    if (eval instanceof Evaluator.IsScope)
        return true;
    if (eval instanceof StructuralEvaluator.Has)
        return false;
    if (eval instanceof CombiningEvaluator) {
        for (Evaluator child : ((CombiningEvaluator) eval).evaluators)
            if (usesScope(child)) return true;
        return false;
    }
    if (eval instanceof StructuralEvaluator.ImmediateParentRun) {
        for (Evaluator child : ((StructuralEvaluator.ImmediateParentRun) eval).evaluators)
            if (usesScope(child)) return true;
        return false;
    }
    if (eval instanceof StructuralEvaluator)
        return usesScope(((StructuralEvaluator) eval).evaluator);
    if (eval instanceof Evaluator.CssNthEvaluator) {
        Evaluator filter = ((Evaluator.CssNthEvaluator) eval).filter;
        return filter != null && usesScope(filter);
    }
    return false;
}

