    static @Nullable Evaluator siblingBranches(Evaluator eval) {
        List<Evaluator> matches = new ArrayList<>();
        if (eval instanceof CombiningEvaluator.Or) {
            for (Evaluator branch : ((CombiningEvaluator.Or) eval).evaluators) {
                if (scopeSiblingAxis(branch) != 0)
                    matches.add(branch);
            }
        } else if (scopeSiblingAxis(eval) != 0) {
            matches.add(eval);
        }
        if (matches.isEmpty())
            return null;
        if (matches.size() == 1)
            return matches.get(0);
        return new CombiningEvaluator.Or(matches);
    }

    /**
     * The root's following element siblings and their descendants, in document order. Non-element siblings are
     * skipped. The tree is only read.
     */
    static Stream<Element> siblingElements(Element root) {
        Stream.Builder<Stream<Element>> streams = Stream.builder();
        for (Element sibling = root.nextElementSibling(); sibling != null; sibling = sibling.nextElementSibling())
            streams.add(sibling.stream());
        return streams.build().flatMap(stream -> stream);
    }

    /** Node-typed variant of {@link #siblingElements(Element)}. */
    static <T extends Node> Stream<T> siblingNodes(Element root, Class<T> type) {
        Stream.Builder<Stream<T>> streams = Stream.builder();
        for (Element sibling = root.nextElementSibling(); sibling != null; sibling = sibling.nextElementSibling())
            streams.add(sibling.nodeStream(type));
        return streams.build().flatMap(stream -> stream);
    }
}

