import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;

public class ScopeProbe3 {
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (Element el : els) { if (sb.length()>0) sb.append(' '); sb.append(el.id().isEmpty()?el.tagName():el.id()); }
        return sb.toString();
    }
    static void t(Element root, String q) {
        try { System.out.printf("%-36s -> %s%n", q, ids(root.select(q))); }
        catch (Exception e) { System.out.printf("%-36s -> ERR %s%n", q, e.getMessage()); }
