        for (Evaluator branch : branches) {
            Breadth needed = deepSiblingBranch(branch) ? Breadth.Subtrees
                : scopeSiblingAxis(branch) == '+' ? Breadth.Immediate : Breadth.Siblings;
            if (needed.ordinal() > breadth.ordinal())
                breadth = needed;
        }
        return breadth;
    }

