        Document doc = Jsoup.parse("<section id=sec><p id=p1></p></section><p id=p2></p>");
        Element sec = doc.expectFirst("#sec");
        // leading combinator behavior unchanged (not :scope)
        System.out.println("> p       => " + ids(sec.select("> p")));
        System.out.println("+ p       => '" + ids(sec.select("+ p")) + "'");
        System.out.println("~ p       => '" + ids(sec.select("~ p")) + "'");
        // whitespace then scope
        System.out.println("  :scope  => " + ids(sec.select("  :scope  ")));
        System.out.println(":scope > p=> " + ids(sec.select(":scope > p")));
